export const html = "<!doctype html><meta charset=\"utf-8\"><title>Raise Readiness Growth Model</title>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Spectral:ital,wght@0,400;0,500;0,600;0,700&family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\">\n<style>\n  :root{\n    --bg:#EAEDF2; --surface:#FFFFFF; --surface-2:#F4F6FA; --surface-3:#EBEFF5;\n    --ink:#151A22; --muted:#57616F; --faint:#8892A1; --line:#E1E6EC; --line-2:#D3DAE3;\n    --navy:#1B2A4A; --brass:#A9803D; --brass-soft:rgba(169,128,61,.12);\n    --good:#2C7A56; --good-soft:rgba(44,122,86,.12);\n    --warn:#B07A1E; --warn-soft:rgba(176,122,30,.14);\n    --track:#E7EBF1;\n    --shadow:0 1px 2px rgba(21,26,34,.04),0 8px 24px -12px rgba(21,26,34,.14);\n  }\n  @media (prefers-color-scheme:dark){\n    :root:not([data-theme=\"light\"]){\n      --bg:#0D1117; --surface:#161C25; --surface-2:#1B222D; --surface-3:#202A36;\n      --ink:#E9EEF5; --muted:#9BA7B6; --faint:#6A7686; --line:#26313D; --line-2:#303D4B;\n      --navy:#8FB0E6; --brass:#CDA467; --brass-soft:rgba(205,164,103,.15);\n      --good:#4FB488; --good-soft:rgba(79,180,136,.14);\n      --warn:#D3A24A; --warn-soft:rgba(211,162,74,.16);\n      --track:#232E3A;\n      --shadow:0 1px 2px rgba(0,0,0,.3),0 10px 30px -14px rgba(0,0,0,.55);\n    }\n  }\n  :root[data-theme=\"dark\"]{\n    --bg:#0D1117; --surface:#161C25; --surface-2:#1B222D; --surface-3:#202A36;\n    --ink:#E9EEF5; --muted:#9BA7B6; --faint:#6A7686; --line:#26313D; --line-2:#303D4B;\n    --navy:#8FB0E6; --brass:#CDA467; --brass-soft:rgba(205,164,103,.15);\n    --good:#4FB488; --good-soft:rgba(79,180,136,.14);\n    --warn:#D3A24A; --warn-soft:rgba(211,162,74,.16);\n    --track:#232E3A;\n    --shadow:0 1px 2px rgba(0,0,0,.3),0 10px 30px -14px rgba(0,0,0,.55);\n  }\n  *{box-sizing:border-box}\n  body{margin:0; background:var(--bg); color:var(--ink);\n    font-family:\"IBM Plex Sans\",system-ui,-apple-system,sans-serif; font-size:15px; line-height:1.5;\n    -webkit-font-smoothing:antialiased}\n  .wrap{max-width:1160px; margin:0 auto; padding:22px 22px 60px}\n  .mono{font-family:\"IBM Plex Mono\",ui-monospace,monospace}\n  .tnum{font-variant-numeric:tabular-nums}\n\n  header.hd{display:flex; align-items:center; gap:15px; flex-wrap:wrap; padding:15px 18px;\n    background:var(--surface); border:1px solid var(--line); border-radius:14px; box-shadow:var(--shadow)}\n  .mark{width:38px;height:38px;border-radius:9px;background:#1B2A4A;color:#EDE2CE;display:grid;\n    place-items:center;font-family:\"Spectral\",serif;font-weight:700;font-size:15px;flex:none}\n  .htitle{display:flex;flex-direction:column;line-height:1.15}\n  .htitle .t{font-family:\"Spectral\",serif;font-weight:600;font-size:18px}\n  .htitle .s{font-size:11px;color:var(--faint);text-transform:uppercase;letter-spacing:.13em}\n  .spacer{flex:1}\n  .tbtn{font:inherit;font-size:12.5px;cursor:pointer;color:var(--muted);background:var(--surface-2);\n    border:1px solid var(--line-2);border-radius:8px;padding:7px 11px}\n  .tbtn:hover{color:var(--ink);border-color:var(--brass)}\n  .tbtn:focus-visible{outline:2px solid var(--brass);outline-offset:2px}\n  .draftpill{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--brass);\n    background:var(--brass-soft);padding:4px 10px;border-radius:999px;font-weight:700}\n\n  .lead{margin:18px 2px 4px;font-family:\"Spectral\",serif;font-size:19px;font-weight:500;\n    max-width:64ch;text-wrap:balance;line-height:1.4}\n  .lead b{color:var(--brass);font-weight:600}\n  .subline{margin:0 2px 20px;font-size:13px;color:var(--muted);max-width:70ch}\n\n  .layout{display:grid;grid-template-columns:340px 1fr;gap:16px;align-items:start}\n  @media(max-width:880px){.layout{grid-template-columns:1fr}}\n\n  .panel{background:var(--surface);border:1px solid var(--line);border-radius:14px;\n    box-shadow:var(--shadow);padding:17px 18px}\n  .panel h3{margin:0 0 3px;font-family:\"Spectral\",serif;font-weight:600;font-size:15px}\n  .panel .ph{font-size:12px;color:var(--faint);margin:0 0 16px}\n\n  .ctl{margin-bottom:17px}\n  .ctl .cl{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:7px}\n  .ctl .cl label{font-size:13px;color:var(--ink);font-weight:500}\n  .ctl .cl .cv{font-family:\"IBM Plex Mono\";font-weight:600;font-size:14px;color:var(--brass)}\n  .ctl .hint{font-size:11px;color:var(--faint);margin-top:5px}\n  input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:5px;border-radius:5px;\n    background:var(--track);outline:none;margin:2px 0}\n  input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:17px;height:17px;border-radius:50%;\n    background:var(--navy);border:2px solid var(--surface);box-shadow:0 1px 4px rgba(0,0,0,.25);cursor:pointer}\n  input[type=range]::-moz-range-thumb{width:17px;height:17px;border-radius:50%;background:var(--navy);\n    border:2px solid var(--surface);cursor:pointer}\n  input[type=range]:focus-visible{outline:2px solid var(--brass);outline-offset:3px}\n  .targetrow{display:flex;align-items:center;gap:10px;margin-bottom:6px}\n  .targetrow input[type=number]{width:82px;font:inherit;font-family:\"IBM Plex Mono\";font-weight:600;\n    font-size:20px;padding:7px 9px;border:1px solid var(--line-2);border-radius:9px;background:var(--surface-2);\n    color:var(--ink);text-align:center}\n  .targetrow input:focus-visible{outline:2px solid var(--brass);outline-offset:1px;border-color:var(--brass)}\n  .targetrow .tl{font-size:13px;color:var(--muted)}\n  .presets{display:flex;gap:7px;margin-top:12px;flex-wrap:wrap}\n  .pbtn{font:inherit;font-size:12px;cursor:pointer;color:var(--muted);background:var(--surface-2);\n    border:1px solid var(--line-2);border-radius:7px;padding:6px 10px}\n  .pbtn:hover{color:var(--ink);border-color:var(--brass)}\n  .pbtn.on{color:var(--ink);border-color:var(--brass);background:var(--brass-soft);font-weight:600}\n  .divider{height:1px;background:var(--line);margin:6px 0 16px}\n  .seclabel{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--faint);\n    font-weight:600;margin:2px 0 12px}\n\n  /* results */\n  .cascade{display:flex;flex-direction:column;gap:8px;margin-bottom:4px}\n  .cstage{display:grid;grid-template-columns:1fr auto;align-items:center;gap:12px;\n    padding:13px 15px;border:1px solid var(--line);border-radius:11px;background:var(--surface-2);\n    position:relative;overflow:hidden}\n  .cstage::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--brass);opacity:.0}\n  .cstage.key::before{opacity:1}\n  .cstage.key{background:var(--surface)}\n  .cstage .lft{display:flex;flex-direction:column;gap:2px}\n  .cstage .nm{font-size:13.5px;font-weight:500}\n  .cstage .cv{font-size:11px;color:var(--faint)}\n  .cstage .big{font-family:\"Spectral\",serif;font-weight:600;font-size:26px;line-height:1;letter-spacing:-.01em}\n  .cstage.key .big{color:var(--brass)}\n  .arrowrate{display:flex;justify-content:flex-end;padding:2px 15px;margin:-4px 0}\n  .arrowrate span{font-size:11px;color:var(--faint);font-family:\"IBM Plex Mono\"}\n\n  .krow{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0 4px}\n  @media(max-width:560px){.krow{grid-template-columns:1fr}}\n  .kbox{background:var(--surface-2);border:1px solid var(--line);border-radius:11px;padding:13px 14px}\n  .kbox .kl{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}\n  .kbox .kv{font-family:\"Spectral\",serif;font-weight:600;font-size:27px;margin-top:6px;line-height:1}\n  .kbox .ks{font-size:11.5px;color:var(--faint);margin-top:5px}\n  .kbox.hero{background:var(--navy);border-color:var(--navy)}\n  .kbox.hero .kl{color:rgba(255,255,255,.7)}\n  .kbox.hero .kv{color:#fff}\n  .kbox.hero .ks{color:rgba(255,255,255,.6)}\n  :root[data-theme=\"dark\"] .kbox.hero,:root:not([data-theme=\"light\"]) .kbox.hero{background:#22314F;border-color:#22314F}\n\n  .split{display:flex;flex-direction:column;gap:12px}\n  .spendtbl{width:100%;border-collapse:collapse;font-size:13px;margin-top:4px}\n  .spendtbl th{text-align:right;font-size:10.5px;text-transform:uppercase;letter-spacing:.07em;\n    color:var(--faint);font-weight:600;padding:0 0 9px;border-bottom:1px solid var(--line)}\n  .spendtbl th:first-child,.spendtbl td:first-child{text-align:left}\n  .spendtbl td{padding:11px 0;border-bottom:1px solid var(--line);font-variant-numeric:tabular-nums}\n  .spendtbl tr:last-child td{border-bottom:none}\n  .spendtbl .m{font-family:\"IBM Plex Mono\"}\n  .spendtbl .ch{display:flex;align-items:center;gap:9px;font-weight:500}\n  .sw{width:9px;height:9px;border-radius:3px;flex:none}\n  .totrow td{font-weight:700;border-top:2px solid var(--line-2);border-bottom:none!important;padding-top:12px}\n\n  .note{margin-top:16px;padding:12px 15px;border:1px solid var(--line);border-left:3px solid var(--brass);\n    border-radius:0 10px 10px 0;background:var(--surface-2);font-size:12.5px;color:var(--muted)}\n  .note b{color:var(--ink);font-weight:600}\n\n  footer.ft{margin-top:30px;padding-top:15px;border-top:1px solid var(--line);\n    display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;font-size:11.5px;color:var(--faint)}\n  footer.ft b{color:var(--muted)}\n</style>\n\n<div class=\"wrap\">\n  <header class=\"hd\">\n    <div class=\"mark\">BVN</div>\n    <div class=\"htitle\">\n      <span class=\"t\">Raise Readiness Growth Model</span>\n      <span class=\"s\">Raetzer PLLC · reverse-engineering the 2027 target</span>\n    </div>\n    <div class=\"spacer\"></div>\n    <span class=\"draftpill\">Working draft</span>\n    <button class=\"tbtn\" id=\"tt\" aria-label=\"Toggle theme\">Theme</button>\n  </header>\n\n  <p class=\"lead\">Start from the outcome and work backward. Set the monthly client target and the conversion rates, and the model shows the <b>qualified assessments, consultations, leads, and ad spend</b> the math requires to get there.</p>\n  <p class=\"subline\">Every rate below is a starting assumption for our call. As we replace them with your real numbers, the required volumes and spend update instantly. Nobody guarantees the outcome. This tells us whether we are mathematically on track.</p>\n\n  <div class=\"layout\">\n    <!-- CONTROLS -->\n    <div class=\"panel\">\n      <h3>Inputs</h3>\n      <p class=\"ph\">The target, then the five rates that move it.</p>\n\n      <div class=\"seclabel\">Monthly target</div>\n      <div class=\"targetrow\">\n        <input type=\"number\" id=\"target\" value=\"28\" min=\"1\" max=\"120\" aria-label=\"New paid clients per month\">\n        <span class=\"tl\">new paid clients<br>per month</span>\n      </div>\n      <div class=\"presets\">\n        <button class=\"pbtn\" data-t=\"9\">Q4 floor · 9</button>\n        <button class=\"pbtn\" data-t=\"18\">Ramp · 18</button>\n        <button class=\"pbtn on\" data-t=\"28\">2027 floor · 28</button>\n      </div>\n\n      <div class=\"divider\"></div>\n      <div class=\"seclabel\">Conversion rates</div>\n\n      <div class=\"ctl\">\n        <div class=\"cl\"><label for=\"close\">Consult to client close</label><span class=\"cv\" id=\"close-v\">45%</span></div>\n        <input type=\"range\" id=\"close\" min=\"15\" max=\"70\" value=\"45\" step=\"1\">\n        <div class=\"hint\">Of consultations held, the share that sign an engagement.</div>\n      </div>\n      <div class=\"ctl\">\n        <div class=\"cl\"><label for=\"show\">Consultation show rate</label><span class=\"cv\" id=\"show-v\">80%</span></div>\n        <input type=\"range\" id=\"show\" min=\"40\" max=\"95\" value=\"80\" step=\"1\">\n        <div class=\"hint\">Of booked consultations, the share that actually attend.</div>\n      </div>\n      <div class=\"ctl\">\n        <div class=\"cl\"><label for=\"book\">Qualified assessment to booking</label><span class=\"cv\" id=\"book-v\">35%</span></div>\n        <input type=\"range\" id=\"book\" min=\"10\" max=\"70\" value=\"35\" step=\"1\">\n        <div class=\"hint\">Of qualified assessments, the share that book a consult.</div>\n      </div>\n      <div class=\"ctl\">\n        <div class=\"cl\"><label for=\"qual\">Assessment qualify rate</label><span class=\"cv\" id=\"qual-v\">80%</span></div>\n        <input type=\"range\" id=\"qual\" min=\"30\" max=\"95\" value=\"80\" step=\"1\">\n        <div class=\"hint\">Of completed assessments, the share routed as qualified.</div>\n      </div>\n      <div class=\"ctl\">\n        <div class=\"cl\"><label for=\"lead\">Lead to completed assessment</label><span class=\"cv\" id=\"lead-v\">55%</span></div>\n        <input type=\"range\" id=\"lead\" min=\"20\" max=\"90\" value=\"55\" step=\"1\">\n        <div class=\"hint\">Of leads that land on the assessment, the share that finish it.</div>\n      </div>\n\n      <div class=\"divider\"></div>\n      <div class=\"seclabel\">Blended cost per lead</div>\n      <div class=\"ctl\">\n        <div class=\"cl\"><label for=\"cpl\">Across live channels</label><span class=\"cv\" id=\"cpl-v\">$28</span></div>\n        <input type=\"range\" id=\"cpl\" min=\"8\" max=\"80\" value=\"28\" step=\"1\">\n        <div class=\"hint\">Weighted across Google Search and LinkedIn in the test phase.</div>\n      </div>\n    </div>\n\n    <!-- RESULTS -->\n    <div class=\"split\">\n      <div class=\"panel\">\n        <h3>What the target requires each month</h3>\n        <p class=\"ph\">Read top down. Each stage is the volume needed to feed the one above it.</p>\n        <div class=\"cascade\" id=\"cascade\">\n          <div class=\"cstage key\"><div class=\"lft\"><span class=\"nm\">New paid clients</span><span class=\"cv\">the target</span></div><span class=\"big tnum\" id=\"r-clients\">28</span></div>\n          <div class=\"arrowrate\"><span id=\"rt-close\">at 45% close ↑</span></div>\n          <div class=\"cstage\"><div class=\"lft\"><span class=\"nm\">Consultations held</span><span class=\"cv\">attended meetings</span></div><span class=\"big tnum\" id=\"r-held\">62</span></div>\n          <div class=\"arrowrate\"><span id=\"rt-show\">at 80% show ↑</span></div>\n          <div class=\"cstage key\"><div class=\"lft\"><span class=\"nm\">Consultations booked</span><span class=\"cv\">calendar bookings</span></div><span class=\"big tnum\" id=\"r-booked\">78</span></div>\n          <div class=\"arrowrate\"><span id=\"rt-book\">at 35% book ↑</span></div>\n          <div class=\"cstage key\"><div class=\"lft\"><span class=\"nm\">Qualified assessments</span><span class=\"cv\">the core leading indicator</span></div><span class=\"big tnum\" id=\"r-qual\">222</span></div>\n          <div class=\"arrowrate\"><span id=\"rt-qual\">at 80% qualify ↑</span></div>\n          <div class=\"cstage\"><div class=\"lft\"><span class=\"nm\">Completed assessments</span><span class=\"cv\">finished the 20 questions</span></div><span class=\"big tnum\" id=\"r-complete\">278</span></div>\n          <div class=\"arrowrate\"><span id=\"rt-lead\">at 55% completion ↑</span></div>\n          <div class=\"cstage\"><div class=\"lft\"><span class=\"nm\">Leads to the assessment</span><span class=\"cv\">top of funnel</span></div><span class=\"big tnum\" id=\"r-leads\">505</span></div>\n        </div>\n      </div>\n\n      <div class=\"krow\">\n        <div class=\"kbox hero\">\n          <div class=\"kl\">Required ad spend</div>\n          <div class=\"kv tnum\" id=\"k-spend\">$14,140</div>\n          <div class=\"ks\">per month, at this cost per lead</div>\n        </div>\n        <div class=\"kbox\">\n          <div class=\"kl\">Cost per new client</div>\n          <div class=\"kv tnum\" id=\"k-cac\">$505</div>\n          <div class=\"ks\">acquisition cost, ad basis</div>\n        </div>\n        <div class=\"kbox\">\n          <div class=\"kl\">Qualified assessments / week</div>\n          <div class=\"kv tnum\" id=\"k-weekly\">51</div>\n          <div class=\"ks\">the weekly pace to watch</div>\n        </div>\n      </div>\n\n      <div class=\"panel\">\n        <h3>Spend allocation · test phase</h3>\n        <p class=\"ph\">Concentrated on the two channels we test first. Adjust the mix on the call.</p>\n        <div style=\"overflow-x:auto\">\n        <table class=\"spendtbl\">\n          <thead><tr><th>Channel</th><th>Share</th><th>Spend</th><th>Leads</th></tr></thead>\n          <tbody id=\"spendbody\">\n            <tr>\n              <td><span class=\"ch\"><span class=\"sw\" style=\"background:var(--navy)\"></span>Google Search</span></td>\n              <td class=\"m\" id=\"g-share\">60%</td><td class=\"m\" id=\"g-spend\">$8,484</td><td class=\"m\" id=\"g-leads\">303</td>\n            </tr>\n            <tr>\n              <td><span class=\"ch\"><span class=\"sw\" style=\"background:var(--brass)\"></span>LinkedIn</span></td>\n              <td class=\"m\" id=\"l-share\">40%</td><td class=\"m\" id=\"l-spend\">$5,656</td><td class=\"m\" id=\"l-leads\">202</td>\n            </tr>\n            <tr class=\"totrow\">\n              <td>Total</td><td class=\"m\">100%</td><td class=\"m\" id=\"t-spend\">$14,140</td><td class=\"m\" id=\"t-leads\">505</td>\n            </tr>\n          </tbody>\n        </table>\n        </div>\n        <div class=\"note\" id=\"reality\">\n          <b>Reading it.</b> At these assumptions the 28 client floor needs a spend well above the $2,000 test budget, which is expected. The test phase proves the rates on a small budget first, then we scale spend only against rates that hold. Move the sliders to your real numbers and watch where the target becomes reachable.\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <footer class=\"ft\">\n    <span>Prepared by <b>BVN</b> for Raetzer PLLC · working model, assumptions to be replaced with live data</span>\n    <span>Reverse funnel · target down to spend</span>\n  </footer>\n</div>\n\n<script>\n  (function(){\n    var root=document.documentElement;\n    function sys(){return matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light';}\n    document.getElementById('tt').addEventListener('click',function(){\n      var cur=root.getAttribute('data-theme')||sys();\n      root.setAttribute('data-theme',cur==='dark'?'light':'dark');\n    });\n\n    var ids=['close','show','book','qual','lead','cpl'];\n    var el={}; ids.forEach(function(i){el[i]=document.getElementById(i);});\n    var target=document.getElementById('target');\n\n    function fmt(n){return Math.round(n).toLocaleString();}\n    function money(n){return '$'+Math.round(n).toLocaleString();}\n\n    function calc(){\n      var T=Math.max(1,+target.value||1);\n      var close=+el.close.value/100, show=+el.show.value/100, book=+el.book.value/100,\n          qual=+el.qual.value/100, lead=+el.lead.value/100, cpl=+el.cpl.value;\n\n      var held=T/close;\n      var booked=held/show;\n      var qa=booked/book;\n      var completed=qa/qual;\n      var leads=completed/lead;\n      var spend=leads*cpl;\n      var cac=spend/T;\n\n      // labels\n      document.getElementById('close-v').textContent=el.close.value+'%';\n      document.getElementById('show-v').textContent=el.show.value+'%';\n      document.getElementById('book-v').textContent=el.book.value+'%';\n      document.getElementById('qual-v').textContent=el.qual.value+'%';\n      document.getElementById('lead-v').textContent=el.lead.value+'%';\n      document.getElementById('cpl-v').textContent='$'+el.cpl.value;\n\n      // cascade\n      document.getElementById('r-clients').textContent=fmt(T);\n      document.getElementById('r-held').textContent=fmt(held);\n      document.getElementById('r-booked').textContent=fmt(booked);\n      document.getElementById('r-qual').textContent=fmt(qa);\n      document.getElementById('r-complete').textContent=fmt(completed);\n      document.getElementById('r-leads').textContent=fmt(leads);\n\n      document.getElementById('rt-close').textContent='at '+el.close.value+'% close ↑';\n      document.getElementById('rt-show').textContent='at '+el.show.value+'% show ↑';\n      document.getElementById('rt-book').textContent='at '+el.book.value+'% book ↑';\n      document.getElementById('rt-qual').textContent='at '+el.qual.value+'% qualify ↑';\n      document.getElementById('rt-lead').textContent='at '+el.lead.value+'% completion ↑';\n\n      // headline boxes\n      document.getElementById('k-spend').textContent=money(spend);\n      document.getElementById('k-cac').textContent=money(cac);\n      document.getElementById('k-weekly').textContent=fmt(qa/4.33);\n\n      // spend split 60/40\n      var gShare=0.6, lShare=0.4;\n      document.getElementById('g-spend').textContent=money(spend*gShare);\n      document.getElementById('l-spend').textContent=money(spend*lShare);\n      document.getElementById('g-leads').textContent=fmt(leads*gShare);\n      document.getElementById('l-leads').textContent=fmt(leads*lShare);\n      document.getElementById('t-spend').textContent=money(spend);\n      document.getElementById('t-leads').textContent=fmt(leads);\n    }\n\n    ids.forEach(function(i){el[i].addEventListener('input',calc);});\n    target.addEventListener('input',function(){calc(); syncPresets();});\n\n    // presets\n    var pbtns=Array.prototype.slice.call(document.querySelectorAll('.pbtn'));\n    function syncPresets(){\n      pbtns.forEach(function(b){ b.classList.toggle('on', +b.getAttribute('data-t')===+target.value); });\n    }\n    pbtns.forEach(function(b){\n      b.addEventListener('click',function(){ target.value=b.getAttribute('data-t'); calc(); syncPresets(); });\n    });\n\n    calc();\n  })();\n</script>\n";
